// The export is a parent-linked tree. Only explicit Paths nodes may fan out.
// Branches execute sequentially. A false filter ends its branch, not siblings.
export function compileGraph(definition, plan) {
  const children = (id) => definition.steps.filter((s) => s.parent_id === id);
  const serial = (v) =>
    JSON.stringify(v ?? {}).replace(/"__proto__"\s*:/g, '["__proto__"]:');
  const lines = [
    "// Owned workflow. Generated by Unzap.",
    "export async function workflow(input, ctx) {",
    "  const output = Object.create(null);",
    "  let completed = false;",
    "  try {",
    '    if (!input || typeof input !== "object" || Array.isArray(input)) throw Error("Expected a JSON object");',
  ];
  const emit = (s, depth = 2) => {
    const indent = "  ".repeat(depth),
      id = JSON.stringify(s.id),
      kids = children(s.id);
    const skip = (node, d) => {
      lines.push(
        "  ".repeat(d) +
          `ctx.skip(${JSON.stringify(node.id)}, ${JSON.stringify(node.kind)});`,
      );
      for (const k of children(node.id)) skip(k, d);
    };
    if (s.kind === "paths") {
      lines.push(
        indent +
          `output[${id}] = await ctx.step(${id}, "paths", async () => ({ sequential: true }));`,
        indent + "{",
        indent + "  let matched = false;",
      );
      const sorted = [...kids].sort(
        (a, b) =>
          (a.params.mode === "fallback") - (b.params.mode === "fallback") ||
          a.params.order - b.params.order,
      );
      for (const p of sorted) {
        const pid = JSON.stringify(p.id),
          decision =
            p.params.mode === "fallback"
              ? "!matched"
              : p.params.mode === "always"
                ? "true"
                : `ctx.filter(ctx.conditions(${serial(p.params.filter_criteria)}, output))`;
        lines.push(
          indent +
            `  output[${pid}] = await ctx.step(${pid}, "path", async () => ${decision});`,
          indent + `  if (output[${pid}]) {`,
          indent + "    matched = true;",
        );
        for (const c of children(p.id)) emit(c, depth + 2);
        if (!children(p.id).length)
          lines.push(indent + "    completed = true;");
        lines.push(indent + "  } else {");
        for (const c of children(p.id)) skip(c, depth + 2);
        lines.push(indent + "  }");
      }
      lines.push(indent + "}");
      return;
    }
    if (s.kind === "webhook")
      lines.push(
        indent +
          `output[${id}] = await ctx.step(${id}, "webhook", async () => ctx.webhook(input, ${serial(s.params)}));`,
      );
    else {
      if (s.kind === 'slack' && s.params.join_channel === true) {
        const joinId = s.id + '__join';
        const joinParams = { channel: s.params.channel, connection: s.params.connection };
        lines.push(indent + `await ctx.step(${JSON.stringify(joinId)}, "slack_join", async () => ctx.action(${serial({ id: joinId, kind: 'slack_join' })}, ctx.resolve(${serial(joinParams)}, output)));`);
      }
      const descriptor = serial({
        id: s.id,
        kind: s.kind,
        action: s.source_action,
      });
      if (['sheets_append','sheets_update'].includes(s.kind)) {
        const resolveId = s.id + '__sheet';
        const resolveParams = { spreadsheet: s.params.spreadsheet, sheet_id: s.params.sheet_id, connection: s.params.connection };
        lines.push(indent + `const sheet_${s.id} = await ctx.step(${JSON.stringify(resolveId)}, "sheets_resolve", async () => ctx.action(${serial({ id: resolveId, kind: 'sheets_resolve' })}, ctx.resolve(${serial(resolveParams)}, output)));`);
      }
      const expression =
        s.kind === "filter"
          ? `ctx.filter(ctx.conditions(${serial(s.params.filter_criteria)}, output))`
          : s.kind === "transform"
            ? `ctx.resolve(${serial(s.params.fields)}, output)`
            : s.kind === "formatter"
              ? `ctx.format(ctx.resolve(${serial(s.params)}, output))`
              : ['sheets_append','sheets_update'].includes(s.kind)
                ? `ctx.action(${descriptor}, {...ctx.resolve(${serial(s.params)}, output), sheet_title: sheet_${s.id}.title})`
                : `ctx.action(${descriptor}, ctx.resolve(${serial(s.params)}, output))`;
      lines.push(
        indent +
          `output[${id}] = await ctx.step(${id}, ${JSON.stringify(s.kind)}, async () => ${expression});`,
      );
    }
    if (s.kind === "filter") {
      lines.push(indent + `if (output[${id}]) {`);
      for (const c of kids) emit(c, depth + 1);
      if (!kids.length) lines.push(indent + "  completed = true;");
      lines.push(indent + "} else {");
      for (const c of kids) skip(c, depth + 1);
      lines.push(indent + "}");
    } else {
      for (const c of kids) emit(c, depth);
      if (!kids.length) lines.push(indent + "completed = true;");
    }
  };
  emit(plan.ordered[0]);
  lines.push(
    '    return ctx.result(completed ? "succeeded" : "filtered", output);',
    "  } catch (error) {",
    '    return ctx.result("held", output, error.message);',
    "  }",
    "}",
  );
  return lines.join("\n");
}
